/**
 * YouTube-surface icons, extracted verbatim from the target site's bundle.
 * Every icon renders through the shared <Svg> base: a square svg sized by
 * `size`, with focusable="false" and aria-hidden="true".
 */

interface SvgProps {
  size?: number;
  className?: string;
  style?: React.CSSProperties;
}

function Svg({
  size = 24,
  viewBox = "0 0 24 24",
  className,
  style,
  children,
}: SvgProps & { viewBox?: string; children: React.ReactNode }) {
  return (
    <svg
      height={size}
      width={size}
      viewBox={viewBox}
      className={className}
      style={style}
      focusable="false"
      aria-hidden="true"
    >
      {children}
    </svg>
  );
}

